def L(unit, sid, f, doc, extra, **kw):
    """a kind written as a list: the school's own questions (doc) and parallel ones (extra) for the Unit Tests"""
    K(unit, sid, f, doc, (lambda r, extra=extra: r.choice(extra)) if extra else None, **kw)
def SF(prompt, v, **kw):
    e = int(math.floor(math.log10(abs(v)))); m = round(v / 10 ** e, 6)
    kw.setdefault("reason", f"= {fmt(m)} × 10{sup(e)}.")
    return TB(prompt + " Give your answer in standard form a × 10ⁿ.", ["a", "n"], [[B(m), B(e)]], skill="Application", **kw)

