    return MC(f"Is {txt} rational or irrational?", ("Rational" if ok else "Irrational") + ": " + why, [(("Irrational" if ok else "Rational") + ": " + w, "Check whether it can be written as a fraction of two integers.") for w in (["it has a root sign or decimal places"] if ok else ["it can be typed on a calculator"])] + [("You cannot tell", "Every real number is either rational or irrational.")], reason=why.capitalize() + ".")
