def _btw(n, cube):
    k = int(round(n ** (1 / 3), 6)) if cube else int(n ** 0.5); s = "∛" if cube else "√"; p = 3 if cube else 2
    return TB(f"Find the two consecutive integers between which {s}{n} lies.", ["Lower integer", "Upper integer"], [[B(k), B(k + 1)]], skill="Reasoning", reason=f"{k}{sup(p)} = {k ** p} and {k + 1}{sup(p)} = {(k + 1) ** p}. {k ** p} < {n} < {(k + 1) ** p}, so {k} < {s}{n} < {k + 1}.")
