def _sfc(a, e1, op, b, e2):
    x, y = D(a).scaleb(e1), D(b).scaleb(e2); v = {"×": x * y, "÷": x / y, "+": x + y, "−": x - y}[op]
    t1, t2 = f"{a} × 10{sup(e1)}", f"{b} × 10{sup(e2)}"
    return SF(f"Calculate ({t1}) {op} ({t2}).", float(v), d="H", reason={"×": "Multiply the first numbers and add the indices", "÷": "Divide the first numbers and subtract the indices", "+": "Make the powers of 10 match, then add", "−": "Make the powers of 10 match, then subtract"}[op] + f": {stdform(float(v))}.")
def _sfcr(r):
    op = r.choice("×÷+−")
    if op == "×": return (str(r.choice([2, 3, 4, 5, 6])), r.randint(2, 6), op, str(r.choice([3, 4, 5, 7])), r.choice([-3, -2, 2, 3, 5]))
    if op == "÷": return (lambda b, q: (str(b * q), r.randint(3, 8), op, str(b), r.choice([-3, -2, 2, 3])))(r.choice([2, 3, 4]), r.choice([2, 3, 1.5, 0.4]))
    e = r.randint(-4, 5); return (r.choice(["4.5", "6.3", "8.4", "5.7"]), e, op, str(r.choice([2, 3, 6])), e - 1)
