def XS(prompt, expr, show, vars="x", **kw): return X(prompt + " Type powers with ^.", expr, vars=vars, show=show, **kw)
def _lawr(r):
    v = r.choice("xyabmp"); m, n = r.randint(2, 9), r.randint(2, 6); k = r.randint(0, 3)
    if k == 0: return (f"{v}{sup(m)} × {v}{sup(n)}", f"{v}^{m + n}", f"{v}{sup(m + n)}", v, "Add the indices.")
    if k == 1: return (f"{v}{sup(m + n)} ÷ {v}{sup(n)}", f"{v}^{m}", f"{v}{sup(m)}", v, "Subtract the indices.")
    if k == 2: return (f"({v}{sup(m)}){sup(n)}", f"{v}^{m * n}", f"{v}{sup(m * n)}", v, "Multiply the indices.")
    return (f"{v}{sup(m + n)} × {v}{sup(-n)}", f"{v}^{m}", f"{v}{sup(m)}", v, "Add the indices: the second one is negative.")
