def _exp(a, b, c, d_):   # (ax + b)(cx + d)
    A, B_, C = a * c, a * d_ + b * c, b * d_
    br = lambda m, k: poly((m, "x"), (k, ""))
    t = f"({br(a, b)})²" if (a, b) == (c, d_) else f"({br(a, b)})({br(c, d_)})"
    return XS(f"Expand and simplify {t}.", f"{A}x^2+({B_})x+({C})", poly((A, "x²"), (B_, "x"), (C, "")), mustNot=["\\("], reason=f"{poly((a * c, 'x²'), (a * d_, 'x'))}{term(b * c, 'x')}{term(b * d_, '')} = {poly((A, 'x²'), (B_, 'x'), (C, ''))}.")
