def _exp2(a, b, c, d_, e, k):   # (x + a)(bx + c) − x(x + d)  or  x(x + a) + (x + b)(x + c)
    if k == 0:
        A, B_, C = b - 1, c + a * b - d_, a * c
        return XS(f"Expand and simplify ({poly((1, 'x'), (a, ''))})({poly((b, 'x'), (c, ''))}) − x({poly((1, 'x'), (d_, ''))}).", f"{A}x^2+({B_})x+({C})", poly((A, "x²"), (B_, "x"), (C, "")), mustNot=["\\("], d="VH", reason=f"{poly((b, 'x²'), (c + a * b, 'x'), (a * c, ''))} − ({poly((1, 'x²'), (d_, 'x'))}) = {poly((A, 'x²'), (B_, 'x'), (C, ''))}.")
