def _cp(v, steps, unit, ask=False):
    out = D(v)
    for s in steps: out = out * (100 + D(str(s))) / 100
    words = ", then ".join(f"{'increases' if s > 0 else 'decreases'} by {abs(s)}%" for s in steps) if len(set(steps)) > 1 or len(steps) == 1 else f"{'increases' if steps[0] > 0 else 'decreases'} by {abs(steps[0])}% in each of {len(steps)} years"
    mult = " × ".join(pc((100 + D(str(s))) / 100) for s in steps)
    if ask: return N(f"A value of {fmt(v)} {words}. Find the overall percentage change (use a negative number for a decrease).", float((out / D(v) - 1) * 100), "%", units=["%"], tol=1e-6, d="VH", reason=f"Multipliers: {mult} = {pc(out / D(v))}, a change of {pc((out / D(v) - 1) * 100)}%.")
    return N(f"A value of {fmt(v)} {unit} {words}. Find the final value.".replace("  ", " "), float(out), d="M" if len(steps) == 1 else "H", tol=0.005, reason=f"{fmt(v)} × {mult} = {pc(out)}.")
