def _sim(a, b, c, d_, x, y, style=0):
    e1 = f"{poly((a, 'x'), (b, 'y'))} = {fmt(a * x + b * y)}"; e2 = f"{poly((c, 'x'), (d_, 'y'))} = {fmt(c * x + d_ * y)}"
    if style: e1 = f"y = {poly((-a, 'x'), (a * x + y, ''))}" if b == 1 else e1
    return TB(f"Solve the simultaneous equations  {e1}  and  {e2}.", ["x", "y"], [[B(x), B(y)]], d="H", skill="Algebra", reason=f"Eliminate one letter by adding or subtracting the equations (or substitute): x = {fmt(x)}, y = {fmt(y)}.")
